True def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    centers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] not in (0, 3)]
    pluses = [(r, c) for r in range(1, h - 1) for c in range(1, w - 1)
              if grid[r][c] == 0 and grid[r-1][c] == 3 and grid[r+1][c] == 3
              and grid[r][c-1] == 3 and grid[r][c+1] == 3]
    colored_arms = set()
    for r, c, _ in centers:
        colored_arms.update(((r, c), (r-1, c), (r+1, c), (r, c-1), (r, c+1)))
    for vertical in (False, True):
        for r, c, color in centers:
            dirs = ((-1, 0), (1, 0)) if vertical else ((0, -1), (0, 1))
            for dr, dc in dirs:
                i, j = r + dr, c + dc
                while 0 <= i < h and 0 <= j < w:
                    if (i, j) in colored_arms and not (abs(i-r) + abs(j-c) <= 1):
                        break
                    if not vertical and any(j == pc for pr, pc in pluses):
                        i, j = i + dr, j + dc
                        continue
                    if grid[i][j] == 0:
                        out[i][j] = color
                    i, j = i + dr, j + dc
    return out
